51	例子3：双色球随机选号。
52	
53	Java 代码：
54	
55	```Java
56	import java.util.List;
57	import java.util.ArrayList;
58	import java.util.Collections;
59	
60	class Test {
61	
62	    /**
63	     * 产生[min, max)范围的随机整数
64	     */
65	    public static int randomInt(int min, int max) {
66	        return (int) (Math.random() * (max - min) + min);
67	    }
68	
69	    public static void main(String[] args) {
70	        // 初始化备选红色球
71	        List<Integer> redBalls = new ArrayList<>();
72	        for (int i = 1; i <= 33; ++i) {
73	            redBalls.add(i);
74	        }
75	        List<Integer> selectedBalls = new ArrayList<>();
76	        // 选出六个红色球
77	        for (int i = 0; i < 6; ++i) {
78	            selectedBalls.add(redBalls.remove(randomInt(0, redBalls.size())));
79	        }
80	        // 对红色球进行排序
81	        Collections.sort(selectedBalls);
82	        // 添加一个蓝色球
83	        selectedBalls.add(randomInt(1, 17));
84	        // 输出选中的随机号码
85	        for (int i = 0; i < selectedBalls.size(); ++i) {
86	            System.out.printf("%02d ", selectedBalls.get(i));
87	            if (i == selectedBalls.size() - 2) {
88	                System.out.print("| ");
89	            }
90	        }
91	        System.out.println();
92	    }
93	}
94	```
95	
96	Python 代码：
97	
98	```Python
99	from random import randint, sample
100	
101	# 初始化备选红色球
102	red_balls = [x for x in range(1, 34)]
103	# 选出六个红色球
104	selected_balls = sample(red_balls, 6)
105	# 对红色球进行排序
106	selected_balls.sort()
107	# 添加一个蓝色球
108	selected_balls.append(randint(1, 16))
109	# 输出选中的随机号码
110	for index, ball in enumerate(selected_balls):
111	    print('%02d' % ball, end=' ')
112	    if index == len(selected_balls) - 2:
113	        print('|', end=' ')
114	print()
115	```
116	
